// after the chase, extra units go home (out of sight) and officers who jumped out of cars walk off
function tidyPolice() {
  const [wx, wy] = crimePos();
  for (let k = cars.length - 1; k >= 0; k--) { const c = cars[k]; if (c.extra && !c.pursuit && !c.returning && near(c.x, c.y, wx, wy) > 30) cars.splice(k, 1); }
  for (let k = footCops.length - 1; k >= 0; k--) { const c = footCops[k]; if (c.extra && !c.chase && !c.returnCar && near(c.x, c.y, wx, wy) > 25) footCops.splice(k, 1); }
}
// what being caught costs. Paying it settles everything, and the car goes back
const HEIST_LOOT=new Set(['diamond','orrery','hotelmasterpiece','hotelharbour','hotelstilllife']);
const stolenGoods=it=>!!it.stolen||HEIST_LOOT.has(it.id);
function confiscateStolenGoods(){
 let count=0;
 for(let k=inv.length-1;k>=0;k--)if(stolenGoods(inv[k])){removeInventoryAt(k);count++;}
 return count;
}
const fineFor = stars => FINE[stars];
function payFine() {
  const f = fineFor(wanted.stars);
  if (wanted.killed || !pay(f)) return false; // (there's no fine for a killing)
  confiscateGun(); // (they keep the gun: gun.js)
  confiscateStolenGoods();
  clearWanted(); return true;
}
// jail: everything you're carrying is taken (not your money) and locked in evidence, and you do your time. Break out
// via the evidence locker and you get it back (see the jailbreak game); serve your time and it's gone
const JAIL_T = 60;
const seized = [];
function goToJail() {
  seized.length = 0; seized.push(...inv);
  clearInventory(); fx.skating = false; fx.boombox = false;
  clearWanted();
}
// ===== notoriety: the city remembers. A crime somebody saw (crime.js: addWanted, or a call that came in with no unit
// to send) makes you known, and so does anything that brings out the air force. Known, people look twice at you in the
// street and the police pick you out from further off; very well known, the odd passer-by gets their phone out. It
// fades a day at a time, and faster if you change how you look: a haircut, a different coat, new ink.
// What happened goes in the papers a day behind, written up in the papers' usual tone (newsLines), and it's on the
// telly, on in the bars, and what people talk about.
// Pure: the score, the log and the headlines. goods-ui.js reads the paper, actions.js the telly, news-ui.js the rest.
// Gentle on purpose: a crime is easy to commit by accident (a red light, a fender bender, a bad moment with a pedestrian),
