    const hx=Math.abs(Math.cos(p.a))*d.halfX+Math.abs(Math.sin(p.a))*d.halfY, hy=Math.abs(Math.sin(p.a))*d.halfX+Math.abs(Math.cos(p.a))*d.halfY;
