  if (d === 'brownstones' || d === 'chinatown' || d === 'shotengai') return 'walkup';
  if (d === 'industrial' || d === 'yards' || d === 'waterfront') return 'freightlobby';
  if (d === 'downtown' || d === 'midtown' && h >= 4) return 'tower';
