  BG[i] = C(f === 5 ? GREEN : BRICK, (1.5 + L * 0.3) * shadeFace(f));
  if (f === 5) return set(i, '=', C(GREEN, L)), true;
  if (f === 3 && Math.abs(HIT.u) < 0.08 && w < 0.2) { BG[i] = C(BRICK, 1); return set(i, w > 0.19 ? '-' : Math.abs(HIT.u) > 0.07 ? '|' : ' ', C(GRAY, L)), true; } // the door
