  for (let k = 0; k < 400; k++) { const gx = LAKE.x + (hash(seed, k, 831) - 0.5) * LAKE.rx * 2, gy = LAKE.y + (hash(seed, k, 832) - 0.5) * LAKE.ry * 2, e = gardenLakeEdge(gx, gy); if (e > lo && e < hi && !onJetty(gx, gy)) return [gx, gy]; }
