    const index=k*2+(side>0),p=sceneFigureTarget(GARDEN_ACTORS[index],...gw(x+side*.045,y+side*.01),0,.17,{k:index,hx:-side,hy:0,pose:'grass',shirt:(side<0?[YEL,BLUE,GREEN]:[MAG,RED,WHITE])[k-1]});
