  addWanted('heist', room.ret[0], room.ret[1], true);
  if (actx) { const at = actx.currentTime; for (let k = 0; k < 30; k++) tone(at + k * 0.11, k & 1 ? 1800 : 2400, 0.09, 0.05, 'square'); }
  say(line, 5);
