  const inside = mode === 'room' && (room.kind === 'grandhotel' || room.kind === 'grandhotelheist' || lobby?.grandHotel) &&
    lobby?.ret?.[0] === hotelAlarm.ret[0] && lobby?.ret?.[1] === hotelAlarm.ret[1];
