const LAP_FRAMES = [
  [' \\o/ ', '  |  ', ' / \\ '], [' _o_ ', '  |  ', ' / > '], ['  o/ ', ' /|  ', ' < \\ '], [' \\o  ', '  |\\ ', '  /\\ '],
  ['  o  ', ' /|\\ ', '  /| '], [' _o  ', '  |\\_', '  |  '], ['  o_ ', '_/|  ', '  |  '], [' \\o/ ', '  |  ', '  |\\ ']];
