    const nr = n[0] * F.r[0] + n[1] * F.r[1] + n[2] * F.r[2], nu = n[0] * F.u[0] + n[1] * F.u[1] + n[2] * F.u[2], phi = Math.atan2(nu, Math.abs(nr)); // (round the side: 0 level, + up)
    const lit = (2.6 + L * 0.6) * faceLit(n) ** 1.3 * burnt * bright;
