  drawTube(P(0.05, 0, 0.062), P(-0.11, 0, 0.055), 0.042 * s, 0.032 * s, skin(false)); // the engine housing
  drawTube(P(-0.12, 0, 0.025), P(-0.5, 0, 0.07), 0.034 * s, 0.013 * s, skin(false)); // the tail boom
