  if (fw && tod >= 21 && tod < 21.1 && toldEvent !== key + ':go') { toldEvent = key + ':go'; say(weather === 'storm' ? 'The fireworks are off: too much wind.' : 'BOOM. The fireworks have started over the bay.', 4); }
