  place(MARINA.x, MARINA.y0 + 2, 'Marina'); place(FAIR.cx, FAIR.y0 + 3, 'Sunset Pier'); place(FISH_HUT.x - 1, FISH_HUT.y - 1, 'Bait & Tackle'); place(WHEEL.x, WHEEL.y - 1.5, 'Ferris wheel');
