        const [[ax, ay], [bx, by]] = [...BIGMAP.pts.values()], d = Math.hypot(bx - ax, by - ay), mx = (ax + bx) / 2, my = (ay + by) / 2;
        if (BIGMAP.pinch) { bigMapPan(mx - BIGMAP.pinch.mx, my - BIGMAP.pinch.my); bigMapZoom(d / BIGMAP.pinch.d, mx, my); }
