    if (y > -1.2 && y < 1.8 && Math.abs(x) < 3.5) { const t = dText(x, y, 0, 0.3, 'AQUA'); return t ? [t, C(BLUE, 15)] : dLit(dCyl(x, 3.5), WHITE, 8); }
    const g = dGlass(x, y, -7, 8, hw, f, [CYAN, null]);
