    if (y > -0.6 && dEll(x, y, 0, -0.6, 8.2, 6) < 1) { const b = dBall(x, y, 0, -0.6, 8.2, 6.6); return Math.abs(y - 2.4) < 0.4 ? ['=', C(WHITE, 13)] : dLit(b, RED, 6); }
