    if (y >= -6 && y < -4.6 && Math.abs(x) < hw - (y < -5.4 ? 1 : 0)) return dLit(0.5 + 0.4 * dCyl(x, hw), GRAY, 8);
    if (y < -4.6 || y > 7.4 || Math.abs(x) > hw) return null;
