    const frame=Math.abs(Math.abs(u)-4.5)>1.18||z<1.07||z>2.03||Math.abs(Math.abs(u)-4.5)<.035;
    BG[i]=C(frame?STONE:CYAN,frame?2+L*.2:1.5+day*2.5);
