// Small native models are assembled once on the finished terrain, then bucketed.
const ISLAND_DETAILS=[];
let islandDetailsB=null;
const FERN_CASCADE=[];

function islandDetail(x,y,hl,hw,z0,z1,kind,angle=0) {
  const model={x,y,hl,hw,z0,z1,kind,c:Math.cos(angle),s:Math.sin(angle)};
  ISLAND_DETAILS.push(model);
  return model;
}
function islandStone(x,y,size,seed) {
  const samples=[terrainHeight(x,y),terrainHeight(x-size,y),terrainHeight(x+size,y),terrainHeight(x,y-size),terrainHeight(x,y+size)];
  const z0=Math.min(...samples)-.025,z1=Math.max(...samples)+size*.3;
  const rock=islandDetail(x,y,size,size*.75,z0,z1,'rock');
  rock.planes=landmarkPlanes(rock.hl,rock.hw,z0,z1,'hip');
  rock.seed=seed;
}
function buildIslandScenery() {
  ISLAND_DETAILS.length=FERN_CASCADE.length=0;
  ISLAND_OBSTACLES.length=0;
  for(const island of WILD_ISLANDS) {
    const [x0,y0,x1,y1]=island.dock;
    for(let x=x0+.25;x<x1-.5;x+=3)for(const y of [y0+.06,y1-.06]) {
      islandDetail(x,y,.035,.035,-.025,.12,'timber');
      islandDetail(x,y,.047,.047,.115,.13,'metal');
    }
    // Small cleats sit away from the boarding point and leave the deck open.
    islandDetail(x0+1.7,y0+.12,.07,.025,0,.035,'metal');
    const [lx,ly]=island.landing;
    islandDetail(lx+1.8,ly+.7,.016,.016,0,.18,'timber');
    const marker=islandDetail(lx+1.8,ly+.7,.12,.018,.13,.185,'sign',Math.PI/2);
    Object.assign(marker,{word:island.name.toUpperCase(),ink:BLACK,labelZ:.1575,labelH:.033});
    for(let y=Math.floor(island.y-island.ry);y<island.y+island.ry;y+=4)for(let x=Math.floor(island.x-island.rx);x<island.x+island.rx;x+=4) {
      const seed=hash(x,y,1910),wx=x+(seed-.5)*2,wy=y+(hash(x,y,1911)-.5)*2,edge=wildIslandEdge(wx,wy,island);
      if(edge<.7||edge>16||onPier(wx,wy)||near(wx,wy,lx,ly)<5||map[idx(Math.floor(wx),Math.floor(wy))])continue;
      const approach=wx>FERN_STRIP.x0-28&&wx<FERN_STRIP.x1+28&&Math.abs(wy-FERN_STRIP.y)<3.5;
      if(island.id==='fern'&&(approach||trailDistance(wx,wy)<.7||near(wx,wy,540,245)<5))continue;
      if(seed<.22&&edge<4&&island.id!=='sand')islandStone(wx,wy,.12+seed*.4,seed);
      else if(seed>.85&&edge>2) {
        const z=terrainHeight(wx,wy);
        islandDetail(wx,wy,.13,.13,z,z+.12,island.id==='sand'?'grass':'shrub').seed=seed;
      }
    }
  }
  const house=FERN_HOUSE;
  // A small dock-facing porch; the former south doorway is closed.
  islandDetail(538.88,245.5,.12,.58,0,.008,'timber');
  islandDetail(538.98,245.86,.025,.035,.23,.28,'lamp');
  Object.assign(islandDetail(538.98,246.35,.265,.018,.285,.32,'sign',Math.PI/2),{word:'FERN HOUSE',houseSign:true,ink:BLACK,labelZ:.3025,labelH:.021});
  const [tx,ty]=house.terrace;
  islandDetail(tx,ty,1.2,1.6,0,.004,'deck');
  for(const y of [244.2,246.8]) {
    islandDetail(tx,y,.58,.12,.045,.055,'timber');
    islandDetail(tx,y+.1,.58,.02,.055,.11,'timber');
    for(const x of [tx-.5,tx+.5])islandDetail(x,y,.025,.09,0,.045,'timber');
  }
  for(const y of [244.15,246.85]) {
    islandDetail(538.65,y,.085,.085,0,.075,'pot');
    islandDetail(538.65,y,.13,.13,.075,.21,'shrub').seed=hash(2,y,1912);
  }
  for(const [x,y,angle]of [[707,110,.3],[711,115,-.4],[703,104,.8]]) {
    if(seaAt(x,y))continue;
    const z=terrainHeight(x,y);
    islandDetail(x,y,.4,.035,z-.025,z+.035,'driftwood',angle);
    islandDetail(x+.18*Math.cos(angle),y+.18*Math.sin(angle),.15,.018,z,z+.055,'driftwood',angle+.8);
  }
  // Low rock shelves flank a continuous, inclined sheet of water. Every end is
  // sampled from terrain, so the cascade joins the creek instead of floating.
  for(let y=187;y<194;y+=.5) {
    const x=FERN_FALLS.x+Math.sin((y-FERN_FALLS.y0)*.6)*.15;
    const za=terrainHeight(x,y)+.012,zb=terrainHeight(x,y+.5)+.012,slope=(zb-za)/.5;
    const z=(za+zb)/2,hw=.25,hl=.16+.035*Math.sin(y*2),thickness=.008;
    const planes=[[1,0,0,hl],[-1,0,0,hl],[0,1,0,hw],[0,-1,0,hw],[0,-slope,1,z],[0,slope,-1,-z+thickness]];
    FERN_CASCADE.push({x,y:y+.25,c:1,s:0,hl,hw,z0:Math.min(za,zb)-thickness,z1:Math.max(za,zb),planes});
    if(Math.floor(y*2)%3===0)for(const side of [-1,1])islandStone(x+side*.34,y+.2,.18+hash(side,y,1913)*.12,hash(side,y,1914));
  }
  for(const [x,y]of [[626.15,196],[627.8,196.2],[627.6,197.7]])islandStone(x,y,.18,hash(x,y,1915));
  buildIslandSights();
  buildCoastLife();
  islandDetailsB=bucketed(ISLAND_DETAILS);
}

function islandTimberShade(model,i,t,L) {
  const top=HIT.face===5,wood=model.kind==='timber'||model.kind==='deck'||model.kind==='driftwood';
  let base=wood?BRICK:GRAY;
  if(model.kind==='trim'||model.kind==='sign')base=STONE;
  if(model.kind==='pot')base=BRICK;
  if(model.kind==='canvas')base=model.base||GREEN;
  if(model.base!==undefined)base=model.base;
  const brightness=(wood?1.6:2.2)+L*(top?.3:.2);
  BG[i]=C(base,brightness);
  if(model.word&&(HIT.face===3||HIT.face===4)) {
    const word=model.houseSign?(homeAt(SHOP[cityPlaceCell('fern-house')])?'FERN HOUSE':'FOR SALE'):model.word;
    const side=HIT.face===3?1:-1,[x,y]=R(model.x-model.s*side*model.hw,model.y+model.c*side*model.hw);
    set(i,worldText(word,HIT.u*side,HIT.w,t,i,x,y,model.labelZ??.195,model.c*side,model.s*side,Math.min(.028,model.hl*1.7/word.length),model.labelH??.04),C(model.ink??BLACK,15));
    return true;
  }
  let ch=' ';
  if(wood) {
    if(top)ch=fract((model.y+HIT.v)*12)<.07?'|':' ';
    else ch=fract(HIT.w*45)<.09?'=':' ';
  }
  else if(model.kind==='metal')ch=top?'=':'|';
  else if(model.kind==='sign')ch=top?'=':' ';
  set(i,ch,C(wood?WARM:base,L*.7));
  return true;
}
function islandRockShade(model,i,t,L) {
  const grain=hash(Math.floor((model.x+HIT.u)*37),Math.floor(HIT.w*59),1916);
  const fraction=(HIT.w-model.z0)/(model.z1-model.z0);
  const moss=fraction<.22&&model.seed>.4&&grain>.3;
  const base=moss?GREEN:GRAY;
  const streak=model.stack&&fraction>.6&&hash(Math.floor((HIT.u+HIT.v)*19),0,1947)>.82;
  BG[i]=C(streak?STONE:base,1.1+L*(HIT.face>=6?.28:.16));
  set(i,streak?'|':model.stack&&fract(HIT.w*9+model.seed)<.045?'_':grain>.96?'.':' ',C(moss?GREEN:STONE,L*.65));
  return true;
}
function drawIslandShrub(model,vx,vy) {
  const grass=model.kind==='grass',height=model.z1-model.z0;
  drawShape(vx,vy,model.z0,model.hl,height,(i,u,z,du,dz,L)=>{
    const sway=Math.sin(T*1.3+model.seed*12)*.006*z/height,local=(u-sway)/model.hl;
    if(grass) {
      if(Math.abs(local)>.8*(1-z/height)||Math.abs(Math.sin(local*12+z*15))<.7)return false;
      set(i,z>height*.8?'\'':'|',C(YEL,L*.75));return true;
    }
    if(local*local+((z-height*.48)/(height*.53))**2>1)return false;
    const grain=hash(Math.floor(u*75),Math.floor(z*75),Math.floor(model.seed*1000));
    if(grain>.88)return false;
    BG[i]=C(GREEN,1.1+L*.18);
    set(i,grain>.73?'\'':grain<.06&&model.seed>.8?'*':' ',C(grain<.06?WARM:GREEN,L*.85));return true;
  });
}
function islandRoofShade(roof,i,t,L) {
  if(roof.cabin.id==='cabin-cove')return coveRoofShade(roof,i,t,L);
  if(roof.part==='chimney') {
    landmarkStone(i,HIT.face<2?HIT.v:HIT.u,HIT.w,GRAY,L);
    if(HIT.w>roof.z1-.035){BG[i]=C(GRAY,1+L*.15);set(i,'=',C(STONE,L*.8));}
    return true;
  }
  const end=HIT.face===2||HIT.face===3,cabin=roof.cabin;
  if(end) {
    BG[i]=C(cabin.wood,1.8+L*.2);
    set(i,fract(HIT.w*32)<.07?'=':' ',C(WARM,L*.6));return true;
  }
  const edge=Math.abs(HIT.v)>roof.hw-.025||HIT.w<roof.z0+.025;
  const seam=fract(HIT.v*9)<.055;
  BG[i]=C(edge?STONE:cabin.roof,1.2+L*(HIT.face===6?.27:.17));
  let mark=seam?'/':' ';
  if(edge)mark='=';
  set(i,mark,C(edge?STONE:cabin.roof,L*.9));
  paintSettledSnow(i,roof.x+HIT.u,roof.y+HIT.v,L,.7,0,HIT.w);
  return true;
}
function islandCabinFacade(i,u,uStep,z,h,d,side,mx,my,fog,wc) {
  const cabin=ISLAND_CABINS.find(c=>mx>=c.x0&&mx<c.x1&&my>=c.y0&&my<c.y1);
  if(!cabin)return;
  if(cabin.id==='fern-house')return fernHouseFacade(cabin,i,z,d,side,wc,fog);
  if(cabin.id==='cabin-cove')return coveFacade(cabin,i,z,h,d,side,wc,fog);
  const light=fog*amb*(side?10:13),along=side?wc-cabin.x0:wc-cabin.y0;
  const width=side?cabin.x1-cabin.x0:cabin.y1-cabin.y0;
  const corner=Math.min(along,width-along),front=side&&py>cabin.y1;
  const terrace=!side&&px<cabin.x0&&cabin.id==='fern-house';
  const door=front&&Math.abs(along-width/2)<.075||terrace&&Math.abs(along-1.5)<.075;
  BG[i]=C(cabin.wood,1.9+light*.19);
  if(front&&cabin.id!=='fern-house'&&wallText(i,along-width/2,uStep,z,d,cabin.room?'SHELTER':'PRIVATE',0,.275,.028,.028,C(STONE,Math.max(light,5)),BG[i]))return;
  if(corner<.045||z>h-.035){BG[i]=C(STONE,2+light*.2);set(i,z>h-.035?'=':'|',C(STONE,light));return;}
  if(z<.04){BG[i]=C(GRAY,1.4+light*.2);set(i,fract(wc*9)<.06?'|':' ',C(STONE,light*.5));return;}
  if(door&&z<.27) {
    const du=front?along-width/2:along-1.5;
    if(Math.abs(du)>.06||z>.255){BG[i]=C(STONE,2+light*.2);set(i,z>.255?'_':'|',C(STONE,light));return;}
    BG[i]=C(GREEN,1.2+light*.12);
    let mark=' ';
    if(z>.17&&z<.24)mark=':';
    else if(Math.abs(du-.037)<.012&&Math.abs(z-.12)<.012)mark='o';
    set(i,mark,C(z>.17?WARM:YEL,Math.max(light,night*8)));return;
  }
  const bay=width===3?.72:.5,spacing=width===3?1.55:1;
  const du=along-bay-Math.round((along-bay)/spacing)*spacing;
  if(Math.abs(du)<.14&&z>.12&&z<.27) {
    const frame=Math.abs(du)>.12||z<.13||z>.26||Math.abs(du)<.009||Math.abs(z-.2)<.007;
    if(frame) {
      BG[i]=C(STONE,2+light*.2);
      set(i,Math.abs(du)<.009?'|':'=',C(STONE,light));return;
    }
    BG[i]=C(night>.35?WARM:CYAN,1.2+night*4);
    set(i,fract(du*4+z*6)<.05?'/':' ',C(WARM,Math.max(light*.65,night*11)));return;
  }
  set(i,fract(z*37)<.075?'=':fract(wc*8)<.025?'|':' ',C(WARM,light*.5));
}
function drawFernCascade() {
  if(near(px,py,FERN_FALLS.x,191)>vis+12)return;
  for(const sheet of FERN_CASCADE) {
    drawBox({...sheet,x:sheet.x-px,y:sheet.y-py},(i,t,L)=>{
      const worldY=sheet.y+HIT.v,flow=fract(worldY*11-T*2.4+Math.sin(HIT.u*31)*.25);
      BG[i]=C(BLUE,1.5+day*2);
      set(i,flow<.22?'~':flow>.92?':':' ',C(flow<.22?WHITE:CYAN,Math.max(4,L)));return true;
    },rayMansard);
  }
  for(let k=0;k<9;k++) {
    const p=fract(T*.65+k*.113),x=FERN_FALLS.x+(hash(k,2,1917)-.5)*.6;
    const y=193.2+p*.25,z=terrainHeight(x,y)+.015+Math.sin(p*Math.PI)*.065;
    drawArt(x-px,y-py,z,.025,.025,[p<.4?'.':'\''],()=>C(WHITE,8+day*3));
  }
}
function drawWildScenery() {
  if(!worldReady||!islandDetailsB)return;
  forNear(islandDetailsB,model=>{
    const vx=model.x-px,vy=model.y-py;
    if(!inView(vx,vy,model.hl+.2))return;
    if(model.kind==='tidepool'){drawIslandTidePool(model);return;}
    if(model.kind==='cover') {
      if((model.cover==='flower'||model.cover==='fern')&&season()==='winter')return;
      if(near(px,py,model.x,model.y)<12)drawShape(vx,vy,model.z0,model.hl,model.z1-model.z0,(i,u,z,du,dz,L)=>islandCoverShade(model,i,u,z,L));
      return;
    }
    if(model.kind==='net'||model.kind==='cloth'||model.kind==='canvas') {
      const sway=model.kind==='cloth'?Math.sin(T*1.7+model.seed)*.012:0;
      drawBox({...model,x:vx,y:vy+sway},(i,t,L)=>islandFabricShade(model,i,t,L),model.planes?rayMansard:rayBox);return;
    }
    if(model.kind==='shrub'||model.kind==='grass'){drawIslandShrub(model,vx,vy);return;}
    if(model.kind==='lamp') {
      drawBox({...model,x:vx,y:vy},(i,t,L)=>{BG[i]=C(WARM,3+night*6);set(i,'o',C(YEL,10+night*5));return true;});return;
    }
    drawBox({...model,x:vx,y:vy},(i,t,L)=>model.kind==='rock'?islandRockShade(model,i,t,L):islandTimberShade(model,i,t,L),model.planes?rayMansard:rayBox);
  });
  for(const roof of ISLAND_ROOFS)if(!(COVE_VIEW.active&&roof.cabin===COVE_VIEW.hiddenCabin)&&inView(roof.x-px,roof.y-py,roof.hl+roof.hw))
    drawBox({...roof,x:roof.x-px,y:roof.y-py},(i,t,L)=>islandRoofShade(roof,i,t,L),rayMansard);
  if(!COVE_VIEW.active){drawCoveExterior();drawFernExterior();}
  const [lx,ly]=WILD_ISLANDS[0].landing;
  if(near(px,py,lx,ly)<vis) {
    drawBox(boxAt(lx+1-px,ly+.7-py,1,0,.12,.08,0,.09),solid(BRICK,{top:'='}));
    drawArt(lx+1-px,ly+.7-py,.105,.25,.035,['TACKLE'],()=>C(WARM,12));
  }
  if(near(px,py,540.5,247)<vis) {
    if(night>.25)for(let k=0;k<4;k++) {
      const p=fract(T*.14+k*.25),x=541.25+p*.17;
      drawShape(x-px,245.1-py,.76+p*.3,.035+p*.04,.05,(i,u,z,du,dz,L)=>{
        if(hash(Math.floor(u*120),Math.floor(z*120),k)>.3)return false;
        set(i,'.',C(GRAY,3));return true;
      });
    }
  }
  drawFernCascade();
  drawIslandLife();
}
// Native island sights: terrain-fitted models, a few residents, and small wildlife.
// Built once and drawn through the existing spatial buckets and figure caches.
const ISLAND_BIRDS=[];
const ISLAND_FLOWERS=[];
function islandGroundModel(x,y,hl,hw,height,kind,obstacle=false) {
  const samples=[terrainHeight(x,y),terrainHeight(x-hl,y-hw),terrainHeight(x+hl,y-hw),terrainHeight(x-hl,y+hw),terrainHeight(x+hl,y+hw)];
  const o=islandDetail(x,y,hl,hw,Math.min(...samples)-.018,Math.max(...samples)+height,kind);
  if(obstacle)ISLAND_OBSTACLES.push(o);
  return o;
}
function islandWaymark(x,y,word,width=.35) {
  width=Math.min(width*.34,.15);
  const z=terrainHeight(x,y);
  islandDetail(x,y,.006,.006,z-.02,z+.145,'timber');
  const sign=islandDetail(x,y,width,.009,z+.095,z+.15,'sign');
  Object.assign(sign,{word,labelZ:z+.1225,labelH:.025,ink:BLACK});
}
function islandCover(x,y,kind,seed,size=.15) {
  if(seaAt(x,y)||onPier(x,y)||map[idx(x,y)]||onFernStrip(x,y,4))return;
  if(ISLAND_CABINS.some(c=>x>c.x0-.2&&x<c.x1+.2&&y>c.y0-.2&&y<c.y1+.4))return;
  size*=.45;
  const z=terrainHeight(x,y),o=islandDetail(x,y,size,size,z,z+(kind==='flower'?.08:kind==='fern'?.065:.09),'cover');
  o.cover=kind;o.seed=seed;
  if(kind==='flower')ISLAND_FLOWERS.push(o);
}
function buildIslandSights() {
  ISLAND_BIRDS.length=ISLAND_FLOWERS.length=0;
  for(const island of WILD_ISLANDS) {
    const paths=island.id==='fern'?FERN_TRAILS:ISLAND_PATHS[island.id];
    for(const path of paths)for(let k=1;k<path.length;k++) {
      const [ax,ay]=path[k-1],[bx,by]=path[k],length=near(ax,ay,bx,by),ux=(bx-ax)/length,uy=(by-ay)/length;
      for(let d=1;d<length;d+=2.6)for(const side of [-1,1]) {
        const seed=hash(ax+d,ay+side,1940),off=.35+seed*.45;
        const x=ax+ux*d-uy*off*side,y=ay+uy*d+ux*off*side;
        islandCover(x,y,island.id==='rock'?'lichen':island.id==='sand'?'rush':seed>.52?'flower':'fern',seed,.13+seed*.1);
      }
    }
    // Resting birds at each landing, clear of the boarding lane. The roost has
    // dark cormorants instead of gulls; flight starts and ends at the same perch.
    for(let k=0;k<3;k++) {
      const x=island.landing[0]+1.1+k*.36,y=island.landing[1]-1.1-k*.2;
      if(!seaAt(x,y))ISLAND_BIRDS.push({x,y,z:terrainHeight(x,y)+.008,seed:k+island.x,kind:island.id==='rock'?'cormorant':'gull',scaredAt:-99});
    }
  }
  // Fern: a small camp beside the existing fire, with rolled mats and a real
  // pitched canvas tent. Foundations and obstacles use the same model geometry.
  const tent=islandGroundModel(528.6,239.2,.43,.32,.27,'canvas',true);
  tent.base=ORANGE;tent.planes=landmarkPlanes(tent.hl,tent.hw,tent.z0,tent.z1,'gable');
  for(const [x,y]of [[527.7,239.2],[526,238.7]])islandGroundModel(x,y,.27,.045,.06,'driftwood');
  const pack=islandGroundModel(528,238.9,.06,.05,.1,'canvas');pack.base=GREEN;
  islandWaymark(527.8,237.85,'WOODLAND CAMP',.45);
  const fire=GRILLS.find(g=>g.on==='fire'&&near(g.x,g.y,525.5,238)<1);
  if(fire) {
    for(let k=0;k<12;k++){const a=k*TAU/12;islandStone(fire.x+Math.cos(a)*.12,fire.y+Math.sin(a)*.12,.023,hash(k,5,1950));}
    for(const side of [-1,1])islandGroundModel(fire.x+side*.045,fire.y,.07,.014,.025,'driftwood');
    islandWaymark(fire.x+.28,fire.y-.2,'FIRE RING',.36);
  }
  for(const [x,y,word]of [[545.5,230.4,'AIRSTRIP'],[590.3,243.5,'FALLS / LOOKOUT'],[603,250.4,'FERN RIDGE']])islandWaymark(x,y,word,.42);
  // A survey cairn and a brass telescope give the ridge a recognisable silhouette.
  for(let k=0;k<3;k++) {
    const r=.18-k*.045,z=terrainHeight(604.1,250.1);
    const stone=islandDetail(604.1,250.1,r,r,z+k*.085,z+(k+1)*.085,'rock');
    ISLAND_OBSTACLES.push(stone);
    stone.seed=.72;stone.planes=landmarkPlanes(r,r,stone.z0,stone.z1,null).concat([[1,0,1,stone.z1+r*.8],[-1,0,1,stone.z1+r*.8],[0,1,1,stone.z1+r*.8],[0,-1,1,stone.z1+r*.8]]);
  }
  const z=terrainHeight(603.8,249.5);
  for(const x of [603.72,603.88])islandDetail(x,249.5,.015,.035,z-.02,z+.18,'metal');
  Object.assign(islandDetail(603.8,249.5,.08,.015,z+.175,z+.205,'metal',Math.PI/2),{base:YEL});
  for(const [x,y]of [[626.3,194.8],[627.9,195.7],[626.1,197.2]])islandCover(x,y,'fern',hash(x,y,1941),.27);
  // Cabin Cove: repaired nets and floats, a fish box, and a little hauled-up skiff.
  for(const x of [488.55,489.65])islandGroundModel(x,395.15,.025,.025,.3,'timber');
  const net=islandGroundModel(489.1,395.15,.55,.01,.27,'net');net.z0=net.z1-.22;
  for(const x of [488.7,489,489.3,489.6]) {
    const z=terrainHeight(x,395.15);
    Object.assign(islandDetail(x,395.15,.025,.025,z+.25,z+.29,'canvas'),{base:WARM});
  }
  islandGroundModel(489.9,395.3,.12,.08,.075,'timber');
  islandSkiff(481,397.2);
  // Cormorant Rock: two solid, faceted sea stacks with bird perches.
  for(const [x,y,hl,hw,height]of [[700.6,350.6,.62,.5,.95],[702.1,352.5,.45,.5,1.25]]) {
    const rock=islandGroundModel(x,y,hl,hw,height,'rock',true);
    rock.seed=.8;rock.stack=true;
    const sx=.4/hl,sy=.35/hw;
    rock.planes=landmarkPlanes(hl,hw,rock.z0,rock.z1,null).concat([
      [1,1,0,hl+hw-.15],[-1,-1,0,hl+hw-.12],
      [sx,0,1,rock.z1+sx*hl*.3],[-sx,0,1,rock.z1+sx*hl*.25],
      [0,sy,1,rock.z1+sy*hw*.45],[0,-sy,1,rock.z1+sy*hw*.3],
    ]);
    ISLAND_BIRDS.push({x,y,z:rock.z1+.008,seed:x,kind:'cormorant',scaredAt:-99});
  }
  islandWaymark(698,353.9,'BIRD ROOST',.4);
  for(let k=0;k<4;k++) {
    const x=699.1+k*.24,y=353.1+Math.sin(k)*.16;
    islandStone(x,y,.045,.5+k*.1);
    const stone=ISLAND_DETAILS[ISLAND_DETAILS.length-1];
    ISLAND_BIRDS.push({x,y,z:stone.z1+.008,seed:30+k,kind:'cormorant',scaredAt:-99});
  }
  // Crescent Sands: a tide pool rim, driftwood ribs, dune flowers and shore birds.
  islandSkiff(710.3,112.7);
  for(const pool of TIDE_POOL_SITES) {
    const samples=[terrainHeight(pool.x,pool.y)];
    for(let k=0;k<8;k++)samples.push(terrainHeight(pool.x+Math.cos(k*TAU/8)*(pool.r+.07),pool.y+Math.sin(k*TAU/8)*(pool.r+.07)));
    const p=islandDetail(pool.x,pool.y,pool.r+.07,pool.r+.07,Math.min(...samples)-.018,Math.max(...samples)+.055,'tidepool'),r=pool.r;
    p.r=r;p.waterZ=p.z1-.022;p.waterRadius=r-.06;
    p.profile=[[p.z0,0],[p.z0,r+.06],[p.z1-.02,r+.05],[p.z1,r],[p.z1-.01,r-.055],[p.z1-.055,r-.08],[p.z1-.06,0]];
    ISLAND_OBSTACLES.push(p);
    for(let k=0;k<6;k++){const a=k*TAU/6;islandCover(pool.x+Math.cos(a)*(pool.r+.17),pool.y+Math.sin(a)*(pool.r+.17),'rush',k/8,.2);}
  }
  for(let k=0;k<3;k++){const x=720.2+k*.35,y=116.35;ISLAND_BIRDS.push({x,y,z:terrainHeight(x,y)+.008,seed:45+k,kind:'gull',scaredAt:-99});}
  islandWaymark(719,115.35,'TIDE POOLS',.38);
  // Juniper: a modest sheltered garden, washing on the line and sea-facing trees.
  for(const y of [241.7,242.5])for(let x=785;x<787.2;x+=.35)islandCover(x,y,'flower',hash(x,y,1943),.13);
  for(const x of [785,787.3])islandGroundModel(x,240.6,.025,.025,.3,'timber');
  const line=islandGroundModel(786.15,240.6,1.15,.006,.29,'metal');line.z0=line.z1-.008;
  for(let k=0;k<4;k++) {
    const cloth=islandGroundModel(785.4+k*.48,240.6,.12,.008,.28,'cloth');
    cloth.z0=cloth.z1-.15;cloth.seed=k;cloth.base=[WHITE,CYAN,STONE,BLUE][k];
  }
  islandWaymark(787,243.85,'SEA GARDEN',.38);
}
function drawIslandTidePool(p) {
  const x=p.x-px,y=p.y-py,r=p.r,water=p.waterZ;
  const stone=(i,t,L)=>{const grain=hash(Math.floor(HIT.u*160),Math.floor(HIT.w*160),1951);BG[i]=C(GRAY,2+L*.22*coveLight(HIT.nx,HIT.ny,HIT.nz)+grain*.5);set(i,' ',0);return true;};
  coveLathe(x,y,0,p.profile,stone);
  drum(x,y,p.waterRadius,water-.003,water,(i,t,L)=>{
    const ripple=Math.sin(HIT.u*80+HIT.v*23+T*.8);
    BG[i]=C(BLUE,3);set(i,ripple>.985?'~':' ',C(CYAN,9));
    const u=HIT.u+r*.28,v=HIT.v-r*.2,angle=Math.atan2(v,u),radius=Math.hypot(u,v);
    if(radius<.025+.018*Math.cos(angle*5)){BG[i]=C(ORANGE,5+L*.3);set(i,' ',0);}
    return true;
  });
  // Shells and a crab sit on the actual lip; seaweed rises out of the bowl.
  coveLathe(x+r*.55,y-r*.65,p.z1-.017,[[0,0],[0,.035],[.014,.028],[.024,.008],[.024,0]],homeStone);
  for(let k=0;k<3;k++)coveTube(x-r*.48+k*.018,y-r*.1,water-.035,x-r*.48+k*.018+.01*Math.sin(T+k),y-r*.1,water+.015,.004,GREEN);
  const cx=x+r*.72,cy=y+r*.47,z=p.z1-.008;
  drawBox(boxAt(cx,cy,1,0,.025,.02,z,z+.025),(i,t,L)=>{BG[i]=C(BRICK,4+L*.25*coveLight(HIT.nx,HIT.ny,HIT.nz));set(i,' ',0);return true;},homeRayEllipsoid);
  for(const side of [-1,1])for(let k=0;k<3;k++)coveTube(cx+side*.015,cy+(k-1)*.013,z+.008,cx+side*.045,cy+(k-1)*.025,z,.003,BRICK);
}
function islandSkiff(x,y) {
  const z=terrainHeight(x,y);
  for(const side of [-1,1])for(let k=0;k<5;k++) {
    const u=(k-2)*.13,width=.12*Math.sqrt(Math.max(0,1-(u/.34)**2));
    islandDetail(x+u,y+side*width,.075,.014,z-.015,z+.07,'driftwood');
  }
  for(const u of [-.2,0,.2])islandDetail(x+u,y,.015,.11,z+.025,z+.045,'timber');
}
function islandCoverShade(model,i,u,z,L) {
  const h=model.z1-model.z0,n=u/model.hl;
  if(Math.abs(n)>1||z<0||z>h)return false;
  if(model.cover==='lichen') {
    if(z>h*.18||n*n+((z-h*.08)/(h*.1))**2>1)return false;
    BG[i]=C(GRAY,2+L*.2);set(i,':',C(YEL,L*.8));return true;
  }
  const stem=Math.abs(n-Math.sin(T*.9+model.seed*8)*.045*z/h)<.06;
  if(model.cover==='flower') {
    const centre=clamp(Math.round(n/.55),-1,1)*.55,head=.7+.1*Math.sin(centre*7+model.seed*9);
    const stalk=Math.abs(n-centre)<.035&&z/h<head;
    const petal=((n-centre)/.13)**2+((z/h-head)/.1)**2<1;
    if(!petal&&!stalk)return false;
    const color=petal?([MAG,YEL,WHITE][Math.floor(model.seed*3)%3]):GREEN;
    BG[i]=C(color,petal?3+L*.35:1+L*.18);set(i,petal?'*':'|',C(color,L*1.1));return true;
  }
  if(model.cover==='rush') {
    if(!stem&&Math.abs(Math.sin(n*14+z*11))<.91)return false;
    set(i,z>h*.8?'\'':'|',C(YEL,L*.85));return true;
  }
  const leaf=Math.abs(n)<(1-z/h)*.9&&Math.sin(z/h*22+Math.abs(n)*8)>.1&&hash(Math.floor(n*15),Math.floor(z/h*18),Math.floor(model.seed*1000))>.2;
  if(!stem&&!leaf)return false;
  BG[i]=C(GREEN,1.4+L*.18);set(i,stem?'|':n<0?'/':'\\',C(GREEN,L*.8));return true;
}
function islandFabricShade(model,i,t,L) {
  if(model.kind==='net') {
    if(fract((HIT.u+model.hl)*25)>.1&&fract(HIT.w*35)>.1)return false;
    set(i,'#',C(GREEN,L*.8+2));return true;
  }
  const base=model.base??STONE;
  BG[i]=C(base,2+L*.3);
  set(i,model.kind==='cloth'&&fract(HIT.u*30)<.08?'|':HIT.w<model.z0+.02?'_':' ',C(base,L));return true;
}
// A small cached seabird body: folded wings on a perch, raised/lowered wings in flight.
ANIMAL_BODIES.islandbird=frame=>{
  const R=AR,parts=[figEll([0,0,3.5],AN_I,[2.2,4,2],()=>R.BODY),figEll([0,3.4,5],AN_I,[1.5,1.7,1.5],()=>R.HEAD),figCap([0,4.6,4.8],[0,6.5,4.5],.5,()=>R.BEAK)];
  for(const side of [-1,1]) {
    if(frame===0)parts.push(figEll([side*1.6,-.5,4],AN_I,[.9,3.3,1.1],()=>R.WING),figCap([side*.8,0,2],[side*.8,.7,.2],.3,()=>R.LEG));
    else {
      const wingZ=frame===3?4:frame===1?7:1.5,tipZ=frame===3?4:frame===1?6:2;
      parts.push(figCap([side*1.5,0,4],[side*7,-1,wingZ],.65,()=>R.WING),figCap([side*7,-1,wingZ],[side*10,-2,tipZ],.35,()=>R.MARK));
      if(frame===3)parts.push(figCap([side*.8,0,2],[side*.8,.7,.2],.3,()=>R.LEG));
    }
  }
  return {parts,decals:animalEyes([0,3.4,5],1.5,1)};
};
// life size, beside people and pigeons: a herring gull ~60 cm nose to tail, a cormorant ~80 cm (the body is ~10.5 units long)
const ISLAND_BIRD_SIZE={gull:.15,cormorant:.2};
const ISLAND_GULL_LOOK=animalLook('islandbird',{body:[WHITE,14],wing:[GRAY,10],mark:[GRAY,2],beak:[YEL,13]});
const ISLAND_CORMORANT_LOOK=animalLook('islandbird',{body:[GRAY,3],wing:[GRAY,2],mark:[GRAY,1],beak:[WARM,10]});
function islandBirdPose(b,time=T) {
  const cycle=mod(time+b.seed*.13,54),scare=time-b.scaredAt;
  const flight=scare>=0&&scare<7?scare/7:cycle>43?(cycle-43)/11:0;
  const lift=Math.sin(flight*Math.PI);
  return {x:b.x+lift*Math.sin(flight*TAU)*1.2,y:b.y+lift*Math.cos(flight*TAU)*.7,z:b.z+lift*.55,
    frame:flight?1+(Math.floor(time*5+b.seed)&1):b.kind==='cormorant'&&Math.sin(time*.2+b.seed)>.2?3:0};
}
function drawIslandLife() {
  if(!worldReady||px<465)return;
  for(const bird of ISLAND_BIRDS) {
    if(near(px,py,bird.x,bird.y)>18)continue;
    if(!freecam&&!paused&&near(px,py,bird.x,bird.y)<.65&&T-bird.scaredAt>12)bird.scaredAt=T;
    const p=islandBirdPose(bird),vx=p.x-px,vy=p.y-py;
    if(!inView(vx,vy,.12))continue;
    drawAnimal(vx,vy,p.z,ISLAND_BIRD_SIZE[bird.kind]??.15,Math.cos(bird.seed),Math.sin(bird.seed),bird.kind==='gull'?ISLAND_GULL_LOOK:ISLAND_CORMORANT_LOOK,p.frame);
  }
  if(rain>.2||season()==='winter')return;
  let drawn=0;
  for(const flower of ISLAND_FLOWERS) {
    if(drawn>=8)break;
    if(near(px,py,flower.x,flower.y)>7)continue;
    const phase=T*.6+flower.seed*TAU,x=flower.x+Math.sin(phase)*.12,y=flower.y+Math.cos(phase*.7)*.1,z=terrainHeight(x,y)+.13+Math.sin(phase*2)*.025;
    if(!inView(x-px,y-py,.02))continue;
    // by night a firefly's glow; by day a butterfly (~8 cm across), wings beating, facing the way it's going
    if(night>.5)drawArt(x-px,y-py,z,.016,.014,['.'],()=>C(YEL,12));
    else drawAnimal(x-px,y-py,z,.026,Math.cos(phase)*.12,-Math.sin(phase*.7)*.07,BUTTERFLY_LOOKS[Math.floor(flower.seed*5)%5],Math.sin(T*12+flower.seed)>0?0:1);
    drawn++;
  }
}
