  const relief=1-smooth(clamp((d/projY/.025-.2)/.65,0,1));
  BG[i]=C(BRICK,3.3+light*.31*coveLight(nx,ny,.1)+grain-joint*1.5+(board%3)*.08+Math.cos(z/.025*Math.PI*2)*.6*relief);
  set(i,' ',0);
