const HOME_LAMP_BULB=[[0,0],[0,.014],[.018,.014],[.032,.030],[.050,.040],[.075,.037],[.094,.022],[.103,0]];
const HOME_LAMP_FABRIC=[[0,.229],[0,.238],[.012,.238],[.408,.140],[.420,.132],[.420,.123],[.408,.131],[.012,.229],[0,.229]];
