    const u=HIT.u+offset,z=HIT.w,grout=Math.max(coveGroove(u,.2,.003,t/projX),coveGroove(z,.2,.003,t/projX));
    const col=(Math.floor(u/.2)+Math.floor(z/.2))&1?BLUE:WHITE;
