      [.031,[[0,0],[0,.056],[.009,.061],[.012,0]],GREEN],
      [.043,[[0,0],[0,.057],[.014,.055],[.017,0]],BRICK],
      [.06,[[0,0],[0,.059],[.004,.059],[.004,0]],YEL],
      [.064,[[0,0],[0,.056],[.014,.056],[.032,.046],[.045,.025],[.049,0]],ORANGE]
