  s.steamDue=T+1.1;
  haze.push({at:placeKey(),kind:'steam',s:1,x:s.x+offsetX,y:s.y+offsetY,z,r:.018,rMax:.06,
    vx:.004,vy:.002,vz:.09,life:1,fade:1/1.6,seed:s.x*13+s.y*7+T});
  while(haze.length>140)haze.shift();
