    const u=clamp((HIT.u/printHalf+1)/2,0,.999),v=clamp((p.z+printHeight-HIT.w)/(2*printHeight),0,.999);
    const k=Math.floor(v*photo.h)*photo.w+Math.floor(u*photo.w),light=clamp(L/12,.25,1);
